DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='qb_subjects_slug_key') THEN ALTER TABLE public.qb_subjects ADD CONSTRAINT qb_subjects_slug_key UNIQUE (slug); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='qb_topics_slug_key') THEN ALTER TABLE public.qb_topics ADD CONSTRAINT qb_topics_slug_key UNIQUE (slug); END IF; END $$;
